'use strict';

// Loupe & Lettres — créé avec l'aide de l'IA
// Compares two CSV exports on one exact key column. Reads text only: no file, network or account access.
const MAX_CHARS = 1000000;
const MAX_ROWS = 10000;

function parseCsv(source, delimiter) {
  if (typeof source !== 'string' || source.length > MAX_CHARS) throw new Error(`CSV must be text of at most ${MAX_CHARS} characters`);
  const text = source.replace(/^﻿/, '');
  const rows = [];
  let row = [], field = '', quoted = false, closed = false;
  const pushField = () => { row.push(field); field = ''; closed = false; };
  const pushRow = () => {
    const wasQuoted = closed;
    pushField();
    // A truly blank line is ignored; an explicit record whose cells are all empty (",", "\"\",\"\"") is kept so it can be refused.
    const blankLine = row.length === 1 && row[0].trim() === '' && !wasQuoted;
    if (!blankLine) rows.push(row);
    row = [];
    if (rows.length > MAX_ROWS + 1) throw new Error(`CSV exceeds ${MAX_ROWS} data rows`);
  };
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (quoted) {
      if (char === '"' && text[i + 1] === '"') { field += '"'; i += 1; }
      else if (char === '"') { quoted = false; closed = true; }
      else field += char;
    } else if (char === delimiter) pushField();
    else if (char === '\n' || char === '\r') {
      if (char === '\r' && text[i + 1] === '\n') i += 1;
      pushRow();
    } else if (char === '"') {
      if (field !== '' || closed) throw new Error('Unexpected quote in CSV');
      quoted = true;
    } else {
      if (closed) throw new Error('Unexpected text after closing CSV quote');
      field += char;
    }
  }
  if (quoted) throw new Error('Unclosed CSV quote');
  if (field !== '' || row.length || closed) pushRow();
  if (!rows.length) throw new Error('CSV is empty');
  return rows;
}

// A plain decimal: optional sign, digits, optional dot and digits. No thousands separator, no exponent.
const DECIMAL = /^[+-]?\d+(?:\.\d+)?$/;
function canonicalDecimal(text) {
  const negative = text.startsWith('-');
  const [whole, fraction = ''] = text.replace(/^[+-]/, '').split('.');
  const w = whole.replace(/^0+(?=\d)/, '');
  const f = fraction.replace(/0+$/, '');
  const body = f ? `${w}.${f}` : w;
  return body === '0' ? '0' : negative ? `-${body}` : body;
}

function readTable(label, source, delimiter, keyColumn) {
  const rows = parseCsv(source, delimiter);
  const headers = rows[0].map(value => value.trim());
  if (headers.some(value => value === '') || new Set(headers).size !== headers.length) throw new Error(`File ${label}: empty or duplicate CSV header`);
  if (!headers.includes(keyColumn)) throw new Error(`File ${label}: missing key column ${keyColumn}`);
  const keyIndex = headers.indexOf(keyColumn);
  const records = rows.slice(1).map((values, index) => {
    const row = index + 2;
    if (values.length !== headers.length) throw new Error(`File ${label}, data row ${row}: column count does not match header`);
    const fields = Object.create(null);
    headers.forEach((name, position) => { fields[name] = values[position].trim(); });
    if (fields[keyColumn] === '') throw new Error(`File ${label}, data row ${row}: key is empty`);
    return { row, key: fields[keyColumn], fields };
  });
  return { label, headers, keyIndex, records };
}

function compareCsv(input) {
  if (!input || typeof input !== 'object') throw new Error('Input must be an object');
  const { key, csvA, csvB } = input;
  const delimiter = input.delimiter === undefined ? ',' : input.delimiter;
  const numericFields = input.numericFields === undefined ? [] : input.numericFields;
  if (typeof key !== 'string' || key.trim() === '') throw new Error('key must name the key column');
  if (typeof delimiter !== 'string' || delimiter.length !== 1 || delimiter === '"' || /[\r\n]/.test(delimiter)) throw new Error('delimiter must be one character other than a quote or a line break');
  if (!Array.isArray(numericFields) || numericFields.some(name => typeof name !== 'string')) throw new Error('numericFields must be a list of column names');
  const keyColumn = key.trim();
  const a = readTable('A', csvA, delimiter, keyColumn);
  const b = readTable('B', csvB, delimiter, keyColumn);
  const common = a.headers.filter(name => b.headers.includes(name));
  for (const name of numericFields) if (!common.includes(name)) throw new Error(`numericFields column ${name} must exist in both files`);
  const compared = common.filter(name => name !== keyColumn);
  const numeric = new Set(numericFields);

  const index = table => {
    const first = new Map(), rowsByKey = new Map();
    for (const record of table.records) {
      if (!first.has(record.key)) first.set(record.key, record);
      rowsByKey.set(record.key, [...(rowsByKey.get(record.key) || []), record.row]);
    }
    const duplicates = [...rowsByKey].filter(([, rows]) => rows.length > 1).map(([k, rows]) => ({ key: k, rows }));
    return { first, duplicates };
  };
  const ia = index(a), ib = index(b);

  const invalidNumeric = [];
  for (const table of [a, b]) {
    for (const record of table.records) {
      for (const name of numericFields) {
        const value = record.fields[name];
        if (value === '') invalidNumeric.push({ file: table.label, row: record.row, key: record.key, field: name, value, reason: 'empty' });
        else if (!DECIMAL.test(value)) invalidNumeric.push({ file: table.label, row: record.row, key: record.key, field: name, value, reason: 'not a plain decimal' });
      }
    }
  }

  const same = (name, left, right) => (numeric.has(name) && DECIMAL.test(left) && DECIMAL.test(right)
    ? canonicalDecimal(left) === canonicalDecimal(right)
    : left === right);
  const changed = [], missingInB = [];
  let identical = 0;
  for (const [k, ra] of ia.first) {
    const rb = ib.first.get(k);
    if (!rb) { missingInB.push({ key: k, row: ra.row }); continue; }
    const fields = compared.filter(name => !same(name, ra.fields[name], rb.fields[name]))
      .map(name => ({ field: name, a: ra.fields[name], b: rb.fields[name] }));
    if (fields.length) changed.push({ key: k, rowA: ra.row, rowB: rb.row, fields });
    else identical += 1;
  }
  const missingInA = [...ib.first].filter(([k]) => !ia.first.has(k)).map(([k, rb]) => ({ key: k, row: rb.row }));

  return {
    key: keyColumn,
    summary: {
      rowsA: a.records.length,
      rowsB: b.records.length,
      matchedKeys: identical + changed.length,
      identical,
      changed: changed.length,
      missingInB: missingInB.length,
      missingInA: missingInA.length,
      duplicateKeysA: ia.duplicates.length,
      duplicateKeysB: ib.duplicates.length,
      invalidNumeric: invalidNumeric.length,
      needsReview: a.headers.length !== common.length || b.headers.length !== common.length || changed.length + missingInB.length + missingInA.length + ia.duplicates.length + ib.duplicates.length + invalidNumeric.length > 0,
    },
    columnsOnlyInA: a.headers.filter(name => !b.headers.includes(name)),
    columnsOnlyInB: b.headers.filter(name => !a.headers.includes(name)),
    missingInB,
    missingInA,
    changed,
    duplicateKeysA: ia.duplicates,
    duplicateKeysB: ib.duplicates,
    invalidNumeric,
    limitations: 'Exact key match after trimming spaces. Only the first row of a repeated key is compared; repeats are listed. needsReview is false only when nothing at all needs a look (columns present in one file only count); a count of identical rows is not a green light. Other columns are compared as trimmed text, except numericFields (plain decimals compared by value). This checks the two files against each other; it does not verify any real payment or order.',
  };
}


return [{ json: compareCsv($input.first().json) }];
